import { generateMatchCode } from "./matchCode.js";
import { MatchStateSchema, ShipSchema } from "./schema.js";

export interface MatchMetadata {
  custom: boolean;
}

/** World updates go out at 20 Hz, the world simulation rate (§15). */
const PATCH_INTERVAL_MS = 1000 / 20;

/**
 * Checks a create or join request before matchmaking places it (Colyseus calls this for every seat request).
 * Refusals carry a readable message the client shows.
