export async function authorizeEntry(options: unknown): Promise<true> {
  const version = (options as { protocolVersion?: unknown } | undefined)?.protocolVersion;
  if (version !== PROTOCOL_VERSION) throw new ServerError(JoinRefusal.ProtocolMismatch, protocolMismatchMessage(version));
  if ((options as { code?: unknown }).code === undefined) {
    if (!createMatchOptionsSchema.safeParse(options).success) throw new ServerError(JoinRefusal.BadRequest, "Malformed match request");
